   "Kolonies van dit gewone zachte koraal zijn variabel van vorm en vormen grote onregelmatige massa's tot 250 mm hoog, meestal met een paar stompe 'vingers' die meestal meer dan 30 mm in diameter zijn.",
   "De kleur varieert van wit tot dof oranje met af en toe geelachtige of bruinachtige kolonies; de poliepen zijn doorschijnend wit.",
   "De dodemansduim komt met enige regelmaat voor langs de Nederlandse kust, op plaatsen waar de dijkvoet met steenstort bekleed is en waar ook vrij veel stroming is, zoals in de Oosterschelde, en in mindere mate ook in de Grevelingen."
