  "facts": [
   "De grootste gele haarkwal spoelde aan in Massachusetts Bay in 1870 en had een hoed met een diameter van 2,3 meter en tentakels van 37 m.",
   "De tentakels zijn geplaatst in 8 groepen, met 70 tot 150 tentakels per groep (maximaal 65 bij de blauwe haarkwal).",
   "De bevruchting van de eicellen vindt in het vrije water plaats, en de larven verblijven enige tijd in het plankton voordat ze naar de bodem zakken om daar een soort poliepje te vormen."
  ],
