  "intro": "De pauwenstaart-viltkokerworm ook wel pauwkokerworm of slijkkokerworm genoemd, is een borstelworm uit de familie Sabellidae.",
  "facts": [
   "Het lichaam van deze 20 cm lange worm bestaat uit een kop, een cilindrisch, gesegmenteerd lichaam en een staartstukje.",
   "De kop bestaat uit een prostomium (gedeelte voor de mondopening) en een peristomium (gedeelte rond de mond) en draagt gepaarde palpen en cirri.",
   "Het dier leeft in een zelfgemaakte woonbuis van gekitte zandkorrels, soms vastgekit op een harde ondergrond, soms gedeeltelijk in zand of slik begraven."
  ],
