  "cat": "Stekelhuidigen",
  "intro": "De paarse zee-egel is een zee-egel uit de familie Strongylocentrotidae, die voorkomt langs de westkust van Noord-Amerika.",
  "facts": [
   "Het dier heeft een paarse kleur, en wordt, exclusief stekels, tot ongeveer 10 centimeter groot.",
   "De paarse zee-egel kan licht waarnemen middels lichtgevoelige cellen, met een resolutie van ongeveer 10 graden.",
   "Het dier wordt daarbij geholpen door de vele stekels, die van de zijkant invallend licht tegenhouden."
  ],
