  "sci": "Echinocardium cordatum",
  "cat": "Stekelhuidigen",
  "intro": "De zeeklit, hartegel of hartvormige zeeklit, Echinocardium cordatum, is een zee-egel die ingegraven in het zand leeft.",
  "facts": [
   "De zeeklit wordt tot 6 centimeter groot, en is bezet met korte grijze stekels.",
   "De zeeklit leeft tot 20 cm diep ingegraven in de zachte zeebodem en kan zich daar ook voortbewegen.",
   "Speciale voetjes van het watervaatstelsel houden een tot 15 cm lange buis naar het bodemoppervlak open, waardoor zuurstofrijk water langs het dier kan stromen."
  ],
