   "Evolutionair gezien staan rondbekken dicht bij het overgangsgebied tussen gewervelde en ongewervelde dieren.Qua uiterlijk lijkt de zeeprik op de paling.",
   "De zeeprik leeft in kustwateren en in zoet water en wordt in bijna alle gematigde zones aangetroffen, behalve in Afrika."
