   "Door stabiele isotopenonderzoek van de jaargroeiringen in de kalk van de doopvontschelp werd bekend dat de zeewatertemperatuur in het midden-Holoceen cycli kende van 11 tot 14 jaar (NB. de zonnevlekcyclus duurt ongeveer 11 jaar).",
   "Er is overigens ook een verwant genaamd Tridacna maxima die ondanks de soortaanduiding maxima, die 'grootste' betekent, vier keer zo klein blijft en blauwer van kleur is."
