   "In één jaar tijd leggen ze zo boven de Stille Oceaan een recordafstand van meer dan 64.000 km af, waarbij ze profiteren van aanhoudende luchtstromen als de passaat en per dag meer dan 900 kilometer kunnen afleggen."
